#!/bin/bash
# Runs as a non-root user in an archlinux:base-devel container, from the repo root.
set -euo pipefail

sudo pacman -Syu --noconfirm --needed namcap
makepkg --syncdeps --noconfirm

# The -debug package is generated by makepkg, not by the recipe. Its build-id
# symlinks point at binaries that live in the main package, which namcap
# reports as dangling when it checks the debug package alone, so it is skipped.
packages=()
for package in ./*.pkg.tar.zst; do
  [[ $package == *-debug-* ]] || packages+=("$package")
done

# namcap exits 0 whatever it finds, so its error lines are detected here.
# Warnings stay advisory.
report=$(namcap PKGBUILD "${packages[@]}" 2>&1)
printf '%s\n' "$report"
if grep -Eq '^Error:| E: ' <<<"$report"; then
  printf '::error::namcap reported errors\n' >&2
  exit 1
fi
